/* ===================== FIGURES ===================== */
const F={};
const T=(x,y,s,c='#E6EDF7',a='middle',sz=13)=>`<text x="${x}" y="${y}" fill="${c}" font-size="${sz}" font-family="IBM Plex Mono" text-anchor="${a}">${s}</text>`;

F.sia=()=>{const ph=[['1','Objectifs','±20 %'],['2','Études prél.',''],['3','Projet','±15 %'],['4','Appels d\'offres','±10 %'],['5','Réalisation',''],['6','Exploitation','']];
return `<svg viewBox="0 0 620 150"><rect width="620" height="150" fill="#0a0f1a"/>${ph.map((p,i)=>{const x=10+i*100;return `<rect x="${x}" y="40" width="90" height="52" rx="6" fill="none" stroke="${i<4?'#FFB347':'#4FD1E8'}" stroke-width="2"/>${T(x+45,62,'SIA '+p[0],'#FFB347',undefined,12)}${T(x+45,78,p[1],'#E6EDF7',undefined,11)}${T(x+45,112,p[2],'#5BD98A',undefined,12)}${i<5?`<path d="M${x+90} 66 L${x+100} 66" stroke="#3a4a6a" stroke-width="2" marker-end=""/>`:''}`}).join('')}${T(310,25,'Norme SIA 112 : les six phases d\'un projet','#8A98B4',undefined,12)}${T(310,140,'précision attendue de l\'estimation des coûts','#5BD98A',undefined,11)}</svg>`};

F.gantt=()=>{const t=[['Signalisation',0,5],['Mesures terrain',5,6],['Profil et GPS',11,4],['Dessins',15,14],['Simulations',29,16]];const u=11;
return `<svg viewBox="0 0 620 200"><rect width="620" height="200" fill="#0a0f1a"/>${[0,1,2,3,4].map(i=>`<line x1="${150+i*110}" y1="20" x2="${150+i*110}" y2="180" stroke="#1c2740"/>`).join('')}
${t.map((x,i)=>`${T(140,44+i*28,x[0],'#8A98B4','end',12)}<rect x="${150+x[1]*u}" y="${34+i*28}" width="${x[2]*u}" height="14" rx="3" fill="#FFB347" opacity=".85"/>`).join('')}
<path d="M${150+11*u} 62 L${150+11*u} 90 L${150+15*u} 90" fill="none" stroke="#4FD1E8" stroke-width="1.5" stroke-dasharray="3 3"/>
<path d="M${150+45*u-6} 168 l6 -10 l6 10 l-6 10 z" fill="#FF6B6B"/>${T(150+45*u,190,'jalon','#FF6B6B',undefined,11)}
${T(300,16,'Le temps en horizontal, les tâches en vertical','#8A98B4',undefined,12)}</svg>`};

F.signal=()=>`<svg viewBox="0 0 620 160"><rect width="620" height="160" fill="#0a0f1a"/>
<rect x="0" y="70" width="620" height="52" fill="#1a2238"/><line x1="0" y1="96" x2="620" y2="96" stroke="#3a4a6a" stroke-dasharray="14 12"/>
<rect x="430" y="74" width="130" height="44" fill="none" stroke="#FF6B6B" stroke-width="2" stroke-dasharray="5 4"/>${T(495,100,'chantier','#FF6B6B',undefined,12)}
${[[110,'1'],[210,'2'],[310,'3'],[380,'4']].map(s=>`<path d="M${s[0]} 40 l14 24 l-28 0 z" fill="none" stroke="#FFB347" stroke-width="2"/>${T(s[0],36,'',undefined,undefined,10)}`).join('')}
${T(250,26,'au maximum 4 éléments verticaux sur un signal avancé','#FFB347',undefined,12)}
${T(310,150,'on installe la signalisation depuis l\'extérieur du chantier','#8A98B4',undefined,11)}</svg>`;

/* ===================== LABORATOIRES ===================== */
const LAB={};
const f2=v=>(''+(Math.round(v*100)/100)).replace('.',',').replace('-','−');

// Devis : le calcul que l'epreuve 1 demande en permanence.
LAB.devis={init:()=>({fn:'Électricien de réseau',t:'Tarif 1',h:40,mat:2500}),
html:s=>`<label>Fonction <select data-k="fn"><option${s.fn==='Électricien de réseau'?' selected':''}>Électricien de réseau</option><option${s.fn==='Chef d\'équipe'?' selected':''}>Chef d'équipe</option><option${s.fn==='Contremaître'?' selected':''}>Contremaître</option><option${s.fn==='Ingénieur chef de projet'?' selected':''}>Ingénieur chef de projet</option><option${s.fn==='Secrétaire'?' selected':''}>Secrétaire</option></select><span></span></label>
<label>Tarif appliqué <select data-k="t"><option${s.t==='Tarif interne'?' selected':''}>Tarif interne</option><option${s.t==='Tarif 1'?' selected':''}>Tarif 1</option><option${s.t==='Tarif 2'?' selected':''}>Tarif 2</option><option${s.t==='Tarif régie'?' selected':''}>Tarif régie</option></select><span></span></label>
<label>Heures de main d'œuvre <input type="range" min="1" max="400" value="${s.h}" data-k="h"><span class="mono">${s.h} h</span></label>
<label>Matériel et engins <input type="range" min="0" max="50000" step="100" value="${s.mat}" data-k="mat"><span class="mono">${s.mat} CHF</span></label>`,
out:s=>{const G={'Électricien de réseau':[92,98,103,110],'Chef d\'équipe':[102,109,115,125],'Contremaître':[124,133,139,150],'Ingénieur chef de projet':[168,180,189,210],'Secrétaire':[78,83,88,96]};
 const i=['Tarif interne','Tarif 1','Tarif 2','Tarif régie'].indexOf(s.t),tx=G[s.fn][i];
 const mo=tx*s.h, ht=mo+ +s.mat, tva=ht*0.081;
 return `<div class="read"><div><small>Tarif horaire</small><span>${tx}.− CHF</span></div><div><small>Main d'œuvre</small><span>${f2(mo)} CHF</span></div><div><small>Total hors taxe</small><span>${f2(ht)} CHF</span></div><div><small>TVA 8,1 %</small><span>${f2(tva)} CHF</span></div><div><small>Total facturé</small><span>${f2(ht+tva)} CHF</span></div><div><small>Écart interne / régie</small><span>${f2((G[s.fn][3]-G[s.fn][0])*s.h)} CHF</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Le tarif 1 est le coût interne majoré des frais de gestion. Le <b>tarif 2 est le tarif 1 majoré de 5 %</b>. Le tarif de régie s'applique quand les heures sont impossibles à estimer d'avance, et il doit être communiqué au client <b>avant</b> les travaux.</p>`}};

// Precision attendue de l'estimation selon la phase SIA : une confusion classique.
LAB.sia={init:()=>({ph:1,cout:800000}),
html:s=>`<label>Phase SIA 112 <select data-k="ph"><option value="1"${s.ph==1?' selected':''}>1 · Définition des objectifs</option><option value="2"${s.ph==2?' selected':''}>3.1 · Avant-projet</option><option value="3"${s.ph==3?' selected':''}>3.3 · Devis principal</option></select><span></span></label>
<label>Coût estimé de l'ouvrage <input type="range" min="50000" max="5000000" step="50000" value="${s.cout}" data-k="cout"><span class="mono">${(+s.cout).toLocaleString('fr-CH')} CHF</span></label>`,
out:s=>{const P=[null,['Estimation des coûts',20],['Estimation sommaire',15],['Devis principal',10]][s.ph];
 const c=+s.cout, d=c*P[1]/100;
 return `<div class="read"><div><small>${P[0]}</small><span>± ${P[1]} %</span></div><div><small>Fourchette basse</small><span>${Math.round(c-d).toLocaleString('fr-CH')}</span></div><div><small>Fourchette haute</small><span>${Math.round(c+d).toLocaleString('fr-CH')}</span></div><div><small>Amplitude</small><span>${Math.round(2*d).toLocaleString('fr-CH')} CHF</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Plus le projet avance, plus l'estimation se resserre : <b>± 20 %</b> à la définition des objectifs, <b>± 15 %</b> à l'avant-projet, <b>± 10 %</b> au devis principal. Annoncer une précision meilleure que celle de la phase où l'on se trouve, c'est promettre ce qu'on ne peut pas tenir.</p>`}};


// Conversion kVA vers amperes et charge d'une cabine de distribution : le calcul
// que l'epreuve 3 demande sans arret, avec les formules empiriques du support.
LAB.cabine={init:()=>({kva:280,ks:1}),
html:s=>`<label>Puissance raccordée <input type="range" min="20" max="600" step="10" value="${s.kva}" data-k="kva"><span class="mono">${s.kva} kVA</span></label>
<label>Facteur de simultanéité <input type="range" min="0.2" max="1" step="0.05" value="${s.ks}" data-k="ks"><span class="mono">${s.ks}</span></label>`,
out:s=>{const kva=+s.kva*+s.ks, a=kva*1.44, pct=a/630*100;
const verdict=pct<60?'sous-chargée':pct<=70?'charge optimale':pct<=100?'chargée':'DÉPASSEMENT';
return `<div class="read"><div><small>Puissance simultanée</small><span>${f2(kva)} kVA</span></div><div><small>Courant (× 1,44)</small><span>${f2(a)} A</span></div><div><small>Charge du jeu de barres 630 A</small><span class="${pct>100?'warn':''}">${f2(pct)} %</span></div><div><small>Verdict</small><span class="${pct>100?'warn':''}">${verdict}</span></div><div><small>Retour en kVA (× 0,695)</small><span>${f2(a*0.695)} kVA</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Formules empiriques du support : <b>kVA × 1,44 = A</b> et <b>A × 0,695 = kVA</b>. Le jeu de barres se dimensionne en règle générale pour <b>630 A</b>, et sa charge optimale se situe entre <b>60 et 70 %</b>, soit 380 à 440 A. On raccorde environ <b>260 à 300 kVA</b> par cabine, facteur de simultanéité compris.</p>`}};


// Tirage de cable : force admissible et longueur maximale. Le piege des unites
// (daN contre kN) signale par les retours d'examen est rendu visible ici.
LAB.tirage={init:()=>({type:'Multiconducteurs',mat:'Cuivre',n:3,sec:150,mu:0.3,poids:4.5}),
html:s=>`<label>Type de câble <select data-k="type"><option${s.type==='Multiconducteurs'?' selected':''}>Multiconducteurs</option><option${s.type==='Unipolaire'?' selected':''}>Unipolaire</option></select><span></span></label>
<label>Conducteur <select data-k="mat"><option${s.mat==='Cuivre'?' selected':''}>Cuivre</option><option${s.mat==='Aluminium'?' selected':''}>Aluminium</option></select><span></span></label>
<label>Nombre de conducteurs <input type="range" min="1" max="4" value="${s.n}" data-k="n"><span class="mono">${s.n}</span></label>
<label>Section d'un conducteur <input type="range" min="16" max="400" step="1" value="${s.sec}" data-k="sec"><span class="mono">${s.sec} mm²</span></label>
<label>Coefficient de frottement <input type="range" min="0.1" max="0.8" step="0.05" value="${s.mu}" data-k="mu"><span class="mono">${s.mu}</span></label>
<label>Poids du câble <input type="range" min="0.5" max="15" step="0.1" value="${s.poids}" data-k="poids"><span class="mono">${s.poids} kg/m</span></label>`,
out:s=>{const S={'Multiconducteurs':{'Cuivre':40,'Aluminium':20},'Unipolaire':{'Cuivre':60,'Aluminium':30}}[s.type][s.mat];
const F=s.n*s.sec*S, Fret=Math.min(F,20000), lmax=Fret/(s.mu*s.poids*10);
return `<div class="read"><div><small>Contrainte admissible</small><span>${S} N/mm²</span></div><div><small>F = n · A · σ</small><span>${f2(F)} N</span></div><div><small>Retenue (plafond 20 000 N)</small><span class="${F>20000?'warn':''}">${f2(Fret)} N</span></div><div><small>En décanewtons</small><span>${f2(Fret/10)} daN</span></div><div><small>En kilonewtons</small><span>${f2(Fret/1000)} kN</span></div><div><small>Longueur maximale</small><span>${f2(lmax)} m</span></div></div><p style="font-size:14px;color:var(--muted);margin:8px 0 0">Contraintes du support : multiconducteurs <b>40 N/mm²</b> en cuivre et <b>20</b> en aluminium, unipolaire <b>60</b> et <b>30</b>. En pratique, la force de traction ne doit <b>jamais dépasser 20 000 N</b>. Longueur maximale : <b>l = F / (µ · M · g)</b>, avec g arrondi à 10. Regarde les trois unités : <b>1 daN = 10 N</b> et <b>1 kN = 1000 N</b>. C'est là que les copies se perdent.</p>`}};

